INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('c-autofilter', 'C* AutoFilter', 'AutoFilter', 'CAPS', 'A versatile selection of filters of varying character in band and lowpass configuration. The cutoff frequency can be modulated by both the input signal envelope and by a fractal oscillator. The default settings provide some sort of an automatic wah effect.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('c-plate-versatile-plate-reverb', 'C* Plate - Versatile plate reverb', 'Plate', 'CAPS', 'This reverb processor is an adaptation of the design discussed in [dat97a]. Tuned for a soft attack and smooth ambience, it consists of a network of twelve delay lines of varying length. At its heart, two of these are modulated very subtly, in a chorus-like fashion.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('c-platex2-stereo-in-out-versatile-plate-reverb', 'C* PlateX2 - Stereo in/out Versatile plate reverb', 'PlateX2', 'CAPS', 'This version of the Plate reverberator comes with stereo inputs.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('c-spice', 'C* Spice', 'Spice', 'CAPS', 'This effect plugin is useful when more bass register definition or more treble presence is called for and generic equalisation does not work without noticeably raising the signal or noise level. A common application is refreshing of material that has been subjected to low-quality analog transmission.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('c-white-white-noise-generator', 'C* White - White noise generator', 'White', 'CAPS', 'Mostly white pseudonoise, mixed and filtered from the output of two Dattorro multibit generators.
