INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('gxdelay-stereo', 'GxDelay-Stereo', 'GxDelay-Stereo', 'Guitarix', 'A stereo delay plugin with independent delay time and delay gain for each channel. It also has a LFO modulator and two modes: linear and pingpong.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('gxdetune', 'Gxdetune', 'Gxdetune', 'Guitarix', 'A detuner with an octave option
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('gxecho-stereo', 'GxEcho-Stereo', 'GxEcho-Stereo', 'Guitarix', 'A stereo echo plugin with independent delay time and delay volume for each channel. It also has a LFO modulator and two modes: linear and pingpong.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('gxexpander', 'GxExpander', 'GxExpander', 'Guitarix', '"The expander is a compressor in reverse. There are two types of expander. In some, signals above the threshold remain at unity gain whereas signals below the threshold are reduced in gain, whereas in others the signal above the threshold also has the gain increased. Therefore you can use an expander as a noise reduction unit. Set the threshold to be just below the level of the player when playing. When the player stops the signal will fall below this threshold and the signal is reduced in gain thus reducing the noise or spill."
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('gxmultibanddelay', 'GxMultiBandDelay', 'GxMultiBandDelay', 'Guitarix', 'A delay that makes it possible to delay every frequency band individually, with crossovers
