INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('mda-detune', 'MDA Detune', 'Detune', 'MDA', 'A low-quality stereo pitch shifter for the sort of chorus and detune effects found on multi-effects hardware.', 'http://moddevices.com/plugins/mda/Detune', '1:0.4-6', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/56c4bd40770cb318f9cd4cd9/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/56c4bd40770cb318f9cd4cd9/thumbnail/', 261, 430, '{"avatarUrl":"https://www.gravatar.com/avatar/ad35377ca6426dd6fbb85267619e7150","name":"MOD Team"}', '["Spectral","Pitch Shifter"]', '[{"default":120,"max":300,"min":0,"name":"Detune"},{"default":50,"max":99,"min":0,"name":"Mix"},{"default":0,"max":20,"min":-20,"name":"Output"},{"default":92.9000015258789,"max":92.9000015258789,"min":5.800000190734863,"name":"Latency"}]');
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('mda-epiano', 'MDA ePiano', 'ePiano', 'MDA', 'It''s a virtual ePiano plugin. Based around 12 carefully sampled and mastered Rhodes Piano samples.', 'http://moddevices.com/plugins/mda/EPiano', '1:0.3-6', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/56c4bd41770cb318f9cd4d14/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/56c4bd41770cb318f9cd4d14/thumbnail/', 319, 368, '{"avatarUrl":"https://www.gravatar.com/avatar/ad35377ca6426dd6fbb85267619e7150","name":"MOD Team"}', '["Generator","Instrument"]', '[{"default":50,"max":100,"min":0,"name":"Envelope Decay"},{"default":50,"max":100,"min":0,"name":"Envelope Release"},{"default":0,"max":50,"min":-50,"name":"Hardness"},{"default":0,"max":50,"min":-50,"name":"Treble Boost"},{"default":0,"max":100,"min":-100,"name":"Modulation"},{"default":23.28499984741211,"max":36.970001220703125,"min":0.07000000029802322,"name":"LFO Rate"},{"default":0,"max":100,"min":0,"name":"Velocity Sense"},{"default":100,"max":200,"min":0,"name":"Stereo Width"},{"default":1,"max":1,"min":0,"name":"Polyphonic"},{"default":0,"max":50,"min":-50,"name":"Fine Tuning"},{"default":7.300000190734863,"max":50,"min":0,"name":"Random Tuning"},{"default":0,"max":100,"min":0,"name":"Overdrive"}]');
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('mda-overdrive', 'MDA Overdrive', 'Overdrive', 'MDA', 'Possible uses include adding body to drum loops, fuzz guitar, and that ''standing outside a nightclub'' sound. This plug does not simulate valve distortion, and any attempt to process organ sounds through it will be extremely unrewarding!', 'http://moddevices.com/plugins/mda/Overdrive', '1:0.4-6', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/56c4bd42770cb318f9cd4d60/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/56c4bd42770cb318f9cd4d60/thumbnail/', 261, 430, '{"avatarUrl":"https://www.gravatar.com/avatar/ad35377ca6426dd6fbb85267619e7150","name":"MOD Team"}', '["Distortion"]', '[{"default":50,"max":100,"min":0,"name":"Drive"},{"default":0,"max":100,"min":0,"name":"Muffle"},{"default":4,"max":20,"min":-20,"name":"Output"}]');
