INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('mda-vocoder', 'MDA Vocoder', 'Vocoder', 'MDA', '16-band vocoder for applying the spectrum of one sound (the modulator, usually a voice or rhythm part) to the waveform of another (the carrier, usually a synth pad or sawtooth wave).
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('highpassfilter', 'HighPassFilter', 'HighPassFilter', 'MOD', 'A simple high pass filter, "Freq" determines its cutoff frequency and "Order" the filter order (or how fast frequencies above the cutoff frequency will decay. Higher the order, faster the decay).', 'http://moddevices.com/plugins/mod-devel/HighPassFilter', '1:0.0-10', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/56c4bd9c770cb318f9cd515a/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/56c4bd9c770cb318f9cd515a/thumbnail/', 312, 453, '{"avatarUrl":"https://www.gravatar.com/avatar/ad35377ca6426dd6fbb85267619e7150","name":"MOD Team"}', '["Filter"]', '[{"default":600,"max":20000,"min":20,"name":"Freq"},{"default":0,"max":2,"min":0,"name":"Order"}]');
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('rkr-distortion', 'rkr Distortion', 'Distortion', 'Rakarrack', 'Adapted from the ZynAddSubFX Distortion
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('sooperlooper', 'SooperLooper', 'SooperLooper', 'MOD', '
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('tap-fractal-doubler', 'TAP Fractal Doubler', 'Fractal Doubler', 'TAP', 'Originally developed to do vocal doubling, this plugin is suitable for doubling tracks with vocals, acoustic/electric guitars, bass and just about any other instrument on them. The effect is created by applying small changes to the pitch and timing of the incoming signal. These changes are created by one-dimensional random fractal lines producing pink noise.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('tap-mono-dynamics', 'TAP Mono Dynamics', 'Mono Dynamics', 'TAP', 'TAP Dynamics is a versatile tool for changing the dynamic content of your tracks. Currently it supports 15 dynamics transfer functions, among which there are compressors, limiters, expanders and noise gates. However, the plugin itself supports arbitrary dynamics transfer functions, so you may add your own functions as well, without any actual programming.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('tap-stereo-dynamics', 'TAP Stereo Dynamics', 'Stereo Dynamics', 'TAP', 'TAP Dynamics is a versatile tool for changing the dynamic content of your tracks. Currently it supports 15 dynamics transfer functions, among which there are compressors, limiters, expanders and noise gates. However, the plugin itself supports arbitrary dynamics transfer functions, so you may add your own functions as well, without any actual programming.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('tap-equalizer-bw', 'TAP Equalizer/BW', 'Equalizer/B', 'TAP', 'This plugin is an 8-band equalizer with adjustable band center frequencies. It allows you to make precise adjustments to the tonal coloration of your tracks. The design and code of this plugin is based on that of the DJ EQ plugin by Steve Harris, which can be downloaded (among lots of other useful plugins) from http://plugin.org.uk.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('tap-pink-fractal-noise', 'TAP Pink/Fractal Noise', 'Pink Noise', 'TAP', 'This plugin came to life as a secondary product of the development of TAP Fractal Doubler. It adds pink noise to the incoming signal using a one-dimensional random fractal line generated by the Midpoint Displacement Method, which is a computationally cheap method suitable for generating random fractals.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('tap-reflector', 'TAP Reflector', 'Reflector', 'TAP', 'This plugin creates a psychedelic reverse audio effect. Overlapping time intervals of incoming samples are treated as blocks called ''fragments''. Each fragment is reversed in time, and faded in and out while played back to the output, hence creating a nearly constant signal level with the mixture resembling a normal reverse-played track -- with the difference that the audio actually progresses forward, only pieces of it are reversed.
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('midi-event-filter', 'MIDI Event Filter', 'MIDI Event Flt.', 'x42', 'Notch style message filter. Suppress specific messages. For flexible note-on/off range see also ''keyrange'' and ''velocityrange''.', 'http://gareus.org/oss/lv2/midifilter#eventblocker', '1:1033.31-10', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/56c4be06770cb318f9cd57ae/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/56c4be06770cb318f9cd57ae/thumbnail/', 511, 279, '{"avatarUrl":"https://www.gravatar.com/avatar/b584786d7ff067757242a8fc219f05c1","name":"Robin Gareus"}', '["Utility","MIDI"]', '[{"default":0,"max":1,"min":0,"name":"Block Control Changes"},{"default":0,"max":1,"min":0,"name":"Block Notes"},{"default":0,"max":1,"min":0,"name":"Block Program Changes"},{"default":0,"max":1,"min":0,"name":"Block Polykey-Pressure"},{"default":0,"max":1,"min":0,"name":"Block Channel-Pressure"},{"default":0,"max":1,"min":0,"name":"Block Pitch Bend"},{"default":0,"max":1,"min":0,"name":"Block Sysex/RT messages"},{"default":0,"max":1,"min":0,"name":"Block custom message"},{"default":0,"max":6,"min":0,"name":"Custom Message Type"},{"default":0,"max":16,"min":0,"name":"Custom message Channel"},{"default":-1,"max":127,"min":-1,"name":"Custom message Data1"},{"default":-1,"max":127,"min":-1,"name":"Custom message Data2"},{"default":0,"max":192000,"min":0,"name":"latency"}]');
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('midi-chromatic-transpose', 'MIDI Chromatic Transpose', 'MIDI Transpose', 'x42', 'Chromatic transpose of midi notes and key-pressure. If an inversion point is set, the scale is mirrored around this point before transposing. Notes that end up outside the valid range 0..127 are discarded.', 'http://gareus.org/oss/lv2/midifilter#miditranspose', '1:1033.31-10', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/56c4be06770cb318f9cd57db/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/56c4be06770cb318f9cd57db/thumbnail/', 331, 229, '{"avatarUrl":"https://www.gravatar.com/avatar/b584786d7ff067757242a8fc219f05c1","name":"Robin Gareus"}', '["Utility","MIDI"]', '[{"default":0,"max":16,"min":0,"name":"Filter Channel"},{"default":0,"max":64,"min":-63,"name":"Transpose"},{"default":0,"max":127,"min":0,"name":"Inversion point"},{"default":0,"max":192000,"min":0,"name":"latency"}]');
