INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('the-infamous-mindi', 'the infamous mindi', 'mindi', 'infamous', 'This is a simple midi message generator that sends a message when you change its message value. It usually requires the host automating it to really be useful.', 'http://ssj71.github.io/infamousPlugins/plugs.html#mindi', '1:0.1-5', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/58f5d3122564d404ad54098f/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/58f5d3122564d404ad54098f/thumbnail/', 347, 219, '{"avatarUrl":"https://www.gravatar.com/avatar/d9304abe28e3642e2e20c963251c1314","name":"Spencer Jackson"}', '["Generator"]', '[{"default":1,"max":1,"min":0,"name":"Enable"},{"default":11,"max":15,"min":8,"name":"Message Type"},{"default":0,"max":15,"min":0,"name":"Channel"},{"default":0,"max":127,"min":0,"name":"Note/CC/PG Number"},{"default":0,"max":127,"min":0,"name":"Value"},{"default":0,"max":2000,"min":0,"name":"1st Msg Repeat Delay Time"},{"default":0,"max":1,"min":0,"name":"Auto Note-Off"}]');
INSERT INTO plugins (id, name, label, brand, description, uri, version, stable, pedalboardCount, screenshotUrl, thumbnailUrl, imageWidth, imageHeight, author, categories, controlPorts) VALUES ('ph-1-phaser-mono', 'PH-1 Phaser[mono]', 'PH-1', 'OverTone', 'Inspired by vintage guitar pedal classics, the PH-1 is a combination of detailed analogue modelling and digital processing which results in a wide range of phasing sounds. From subtle shimmer to rich rotating speaker effects, it can be used to enhance all instruments or even an entire mix.', 'http://overtonedsp.co.uk/lv2/ph1.lv2', '1:2.0-2', 1, 0, 'https://api.moddevices.com/v2/lv2/plugins/5b0dda3e2564d45bb224f55f/screenshot/', 'https://api.moddevices.com/v2/lv2/plugins/5b0dda3e2564d45bb224f55f/thumbnail/', 261, 430, '{"avatarUrl":"https://www.gravatar.com/avatar/8d4a318064bd854cdf36999de0df5da2","name":"OverToneDSP"}', '["Modulator","Phaser"]', '[{"default":0.10000000149011612,"max":4,"min":0.10000000149011612,"name":"Speed Hz"}]');
